import {
  AutoMovieLoftViewFullSource,
  AutoMovieNaturalSpline,
} from "@automovie/engine";
import type {
  AutoMovieVector3Tuple,
  IAutoMovieHumanMammaryJoin,
  IAutoMovieLoftSectionFrame,
  IAutoMovieLoftViewFullSource,
  IAutoMovieNaturalCubicSpline,
  IAutoMovieSolidSharedCurve,
  IAutoMovieViewPart,
} from "@automovie/interface";

/**
 * The breast's footprint on the chest wall and the loop where the trunk's skin
 * meets it, generated by rule from the person's own points.
 *
 * Four quarter ellipses in the breast's section chart connect the four
 * anatomical extremes read from the person's landmarks. Using these ellipses
 * between landmarks is an ESTIMATE of the base's outline.
 *
 * - Up: the breast's upper border straight below the midclavicular point by the
 *   person's own midclavicular-to-nipple distance times `CSL / CNL` (Demiroz et
 *   al. 2021, below; both lengths are measured down from the midclavicular
 *   point, their Fig. 1);
 * - Down: the fold's lowest point, at the level of the point on the trunk's
 *   anterior median skin line `TAP_INDEX` of the surface distance from
 *   suprasternale down to the umbilicus (Fujisawa et al. 2021, below, who
 *   measure along the skin): the fold is placed on the trunk's own midline
 *   landmarks. Nipple-to-fold distance also depends on volume and ptosis;
 * - Medial: the lateral sternal border, `STERNUM_HALF_SHARE` of the sternum's
 *   length off the median plane;
 * - Lateral: the anterior axillary line, through the armpit's front fold point.
 *
 * The footprint dropped on the trunk's skin, each point along the trunk's own
 * radius in its level section, is the loop both parts share; the breast's
 * family extends inward to take it as its proximal section, and the shared-loop
 * join's fold of stated radius meets the two there.
 *
 * Source: Demiroz A, Turkmen A, Yildiz TF, Daghan B. Anthropometric breast
 * measurements of young women with no history of pregnancy or surgery in
 * Turkey. J Plast Surg Hand Surg 2021;55(1):13-16 (88 women aged 18 to 30, BMI
 * 18.5 to 25, standing, both sides).
 */
export namespace AutoMovieHumanMammaryJoin {
  type V = AutoMovieVector3Tuple;

  /**
   * Midclavicular point to the breast's upper border, mm: Demiroz et al. 2021,
   * CSL, the mean of 10.2 (right) and 9.9 (left) cm.
   */
  export const CSL_MM: number = 100.5;

  /**
   * Midclavicular point to the nipple, mm: Demiroz et al. 2021, CNL, the mean
   * of 19.1 (right) and 19.4 (left) cm.
   */
  export const CNL_MM: number = 192.5;

  /**
   * Xiphion's height from the hip centres' midpoint to suprasternale, a share:
   * de Leva 1996 (J Biomech 29(9):1223-1230), Table 4, women, suprasternale
   * 529.3 mm and xiphion 142.5 mm below it, both measured from the hip centres'
   * midpoint (MIDH): `1 - 142.5 / 529.3`.
   */
  export const XIPHION_SHARE: number = 1 - 142.5 / 529.3;

  /**
   * The umbilicus's height from the hip centres' midpoint to suprasternale, a
   * share, used only when the person has no navel site (`IPoints.umbilicus`
   * absent): de Leva 1996, Table 4, women, OMPH-MIDH over SUPR-MIDH, `181.5 /
   * 529.3`.
   */
  export const UMBILICUS_FALLBACK_SHARE: number = 181.5 / 529.3;

  /**
   * The inframammary fold's lowest point on the midline, from suprasternale
   * toward the umbilicus, a share of the surface distance between them along
   * the anterior median line (the thorax anthropometric position index):
   * Fujisawa, Ito, Aoyama, Kiuchi, Araki, Nakao and Nakagawa, Thorax
   * anthropometric position index: a simple evaluation of the inframammary fold
   * position in the thorax, J Plast Surg Hand Surg 2021;55(1):21-24, 145 women
   * standing, 0.590 +- 0.038 (suprasternale to the fold 22.3 +- 1.9 cm, to the
   * umbilicus 37.8 +- 2.8 cm). Their Table 2: 0.582 under 50 years and 0.603
   * from 50, age the only independent factor; the person has no age field, so
   * 0.590 is the population mean, stated as such. Fujisawa measure to the
   * umbilicus's superior border and the person's navel site is its centre
   * (ANSUR II omphalion); the difference, a few millimetres, is an ESTIMATE
   * left in. Cross-check: ANSUR II waist front length (suprasternale to
   * anterior omphalion along the skin, sitting) is 355.1 +- 23.9 mm for women
   * (`packages/human/docs/sources/ansur-ii-course-measures.md`, no. 89), within
   * one SD of Fujisawa's 378 +- 28 standing.
   */
  export const TAP_INDEX: number = 0.59;

  /**
   * Half the sternal body's breadth over the sternum's length from
   * suprasternale to the xiphisternal joint, a share: the lateral sternal
   * border's distance from the median plane. Atesoglu, Deniz and Uslu,
   * Evaluation of the morphological characteristic and sex differences of
   * sternum by multi-detector computed tomography, Folia Morphol
   * 2018;77(3):489-497, Table 1, 103 women: the corpus sterni 27.8 mm wide at
   * the 4th-5th costal notches (CSWc), the level of the breast's medial
   * extreme, and the manubrium and corpus 133.1 mm long together; `27.8 / 2 /
   * 133.1`. Both are bone measures on straightened MDCT reconstructions: the
   * breadth is the bony corpus's, without the cartilage or the skin over it,
   * and the length is the straight sternal length, not a surface distance. The
   * person's sternum is read from suprasternale down to xiphion's height.
   */
  export const STERNUM_HALF_SHARE: number = 27.8 / 2 / 133.1;

  /**
   * Clocks a loop is sampled at before its spline joins them: one a degree and
   * a half.
   */
  const CLOCKS: number = 240;

  /** The person's points, as the interface states them. */
  export type IPoints = IAutoMovieHumanMammaryJoin.IPoints;

  /** The footprint, as the interface states it. */
  export type IFootprint = IAutoMovieHumanMammaryJoin.IFootprint;

  /**
   * ESTIMATE of the sagittal-arc sampling pitch in mm for centimetre-scale
   * curvature.
   */
  const ARC_STEP_MM: number = 0.5;

  /**
   * The inframammary fold's level on the host's anterior median skin line: the
   * point `TAP_INDEX` of the surface distance from suprasternale's level down
   * to the umbilicus's (the person's navel site, or `UMBILICUS_FALLBACK_SHARE`
   * of mid-hip to suprasternale without one), measured along the skin as
   * Fujisawa et al. measure it.
   *
   * @param host The host's complete source: a straight course with level
   *   sections whose chart's phase 0 is the anterior median line (the
   *   trunk's).
   * @param points The person's points.
   * @evidence contracts/development/implementation.md#principled-implementation The surface distance along the anterior median line, by the source's own definition, not the height between the two levels.
   * @evidence contracts/development/implementation.md#clear-and-simple-structure One line sampled, one cumulative length, one interpolation.
   * @evidence contracts/development/implementation.md#prohibited-implementation-shortcuts A host that is not straight and level, a phase-0 line off the median plane and a level outside the host's stations are refused with their numbers.
   * @evidence contracts/development/implementation.md#efficient-algorithms One source point per half millimetre of the line.
   * @evidence contracts/development/implementation.md#reuse-equivalent-work The footprint and the native under-bust site read this one point.
   * @evidence contracts/development/implementation.md#bound-retention-and-release-resources Returns one point.
   * @evidence contracts/development/common.md#meaningful-documentation States the line, the measure and the fallback.
   */
  export function foldPoint(
    host: IAutoMovieViewPart,
    points: Pick<IPoints, "suprasternale" | "hips" | "umbilicus">,
  ): V {
    const source: IAutoMovieLoftViewFullSource.IReader =
      AutoMovieLoftViewFullSource.create(host);
    const { foot, tangent } = straight(host, source);
    const p = points;
    const station = (q: V): number =>
      source.domain[0] + dot(sub(q, [...foot.origin] as V), tangent);
    const umbilicus: V =
      p.umbilicus ??
      add(
        p.hips,
        scale(sub(p.suprasternale, p.hips), UMBILICUS_FALLBACK_SHARE),
      );
    const [top, bottom]: [number, number] = [
      station(p.suprasternale),
      station(umbilicus),
    ];
    if (!(bottom > source.domain[0] && top < source.domain[1] && top > bottom))
      throw new Error(
        "mammary: suprasternale's station " +
          top +
          " and the umbilicus's " +
          bottom +
          " are not inside the host's " +
          source.domain.join(" to "),
      );
    const count: number = Math.ceil((top - bottom) / ARC_STEP_MM);
    const stations: number[] = Array.from(
      { length: count + 1 },
      (_, i: number): number => top - ((top - bottom) * i) / count,
    );
    const line: V[] = stations.map(
      (s: number): V => [...source.point(s, 0)] as V,
    );
    const lateral: V = [...foot.v] as V;
    if (
      !line.every(
        (q: V): boolean =>
          Math.abs(dot(sub(q, p.suprasternale), lateral)) <=
          1e-6 * Math.max(1, Math.abs(dot(sub(q, p.suprasternale), tangent))),
      )
    )
      throw new Error(
        "mammary: the host's phase-0 line does not run on suprasternale's median plane",
      );
    const run: number[] = [0];
    for (let i: number = 1; i < line.length; ++i)
      run.push(run[i - 1]! + Math.hypot(...sub(line[i]!, line[i - 1]!)));
    const target: number = TAP_INDEX * run.at(-1)!;
    const i: number = run.findIndex((r: number): boolean => r >= target);
    const t: number =
      i <= 0 ? 0 : (target - run[i - 1]!) / (run[i]! - run[i - 1]!);
    return [
      ...source.point(
        i <= 0 ? top : stations[i - 1]! + (stations[i]! - stations[i - 1]!) * t,
        0,
      ),
    ] as V;
  }

  /**
   * The footprint for a breast course, by the rule above.
   *
   * @param frame The breast course's section frame at its start
   *   (`AutoMovieHumanConicLoft.axis(family).at(start)`).
   * @param points The person's points.
   * @param host The host the fold's level is read on (`foldPoint`).
   * @evidence contracts/development/implementation.md#principled-implementation Each reach is one named landmark projected on the course's section chart: the upper border Demiroz's CSL / CNL of the person's midclavicular-to-nipple distance straight below the midclavicular point, the fold at Fujisawa's index of the surface distance from suprasternale to the umbilicus, the sternal border off the median plane by its share of the sternum's length, the anterior axillary line through the armpit's front fold point.
   * @evidence contracts/development/implementation.md#clear-and-simple-structure Four projections and one refusal.
   * @evidence contracts/development/implementation.md#prohibited-implementation-shortcuts A reach that is not positive and finite is refused with all four; nothing is clamped.
   * @evidence contracts/development/implementation.md#efficient-algorithms Constant work besides the fold's line.
   * @evidence contracts/development/implementation.md#reuse-equivalent-work The footprint serves every read of the loop.
   * @evidence contracts/development/implementation.md#bound-retention-and-release-resources Returns plain numbers.
   * @evidence contracts/development/common.md#meaningful-documentation States each extreme's landmark and source.
   */
  export function footprint(
    frame: IAutoMovieLoftSectionFrame,
    points: IPoints,
    host: IAutoMovieViewPart,
  ): IFootprint {
    const origin: V = [...frame.origin] as V,
      u: V = [...frame.u] as V,
      v: V = [...frame.v] as V;
    const along: V = cross(v, u);
    const p = points;
    const midclavicular: V = scale(add(p.suprasternale, p.shoulder), 0.5);
    const upper: V = sub(
      midclavicular,
      scale(
        p.up,
        (CSL_MM / CNL_MM) * Math.hypot(...sub(p.bust, midclavicular)),
      ),
    );
    const xiphion: number =
      dot(p.hips, p.up) +
      XIPHION_SHARE * (dot(p.suprasternale, p.up) - dot(p.hips, p.up));
    const lateral: V = dot(v, [0, 0, 1]) > 0 ? v : scale(v, -1);
    const up: number = dot(sub(upper, origin), u);
    const fold: number = dot(foldPoint(host, p), p.up);
    const down: number = (dot(origin, p.up) - fold) / dot(u, p.up);
    const outward: number = dot(sub(p.armpitFront, origin), lateral);
    const border: number =
      STERNUM_HALF_SHARE * (dot(p.suprasternale, p.up) - xiphion);
    const inward: number = (origin[2] - border) / lateral[2];
    const reaches =
      lateral === v
        ? { up, down, plusV: outward, minusV: inward }
        : { up, down, plusV: inward, minusV: outward };
    if (
      !Object.values(reaches).every(
        (r: number): boolean => r > 0 && Number.isFinite(r),
      )
    )
      throw new Error(
        "mammary: the footprint's reaches are not all positive: " +
          JSON.stringify(reaches),
      );
    return { origin, along, u, v, reaches };
  }

  /**
   * The footprint's point at clock `c` in its plane, mm, `c = 0` up and rising
   * toward `+v`: four quarter ellipses about the course (ESTIMATE of the base's
   * outline between its four extremes).
   *
   * @evidence contracts/development/implementation.md#principled-implementation Each quadrant is the ellipse quarter on its two reaches, so the extremes' tangents are square to their axes.
   * @evidence contracts/development/common.md#meaningful-documentation States the clock's zero and sense.
   */
  export function at(f: IFootprint, c: number): V {
    const [x, y]: [number, number] = [Math.cos(c), Math.sin(c)];
    const a: number = x >= 0 ? f.reaches.up : f.reaches.down;
    const b: number = y >= 0 ? f.reaches.plusV : f.reaches.minusV;
    return add(f.origin, add(scale(f.u, a * x), scale(f.v, b * y)));
  }

  /** The loop, as the interface states it. */
  export type ILoop = IAutoMovieHumanMammaryJoin.ILoop;

  /**
   * The footprint dropped on the host's skin: at each sampled clock the host's
   * skin at the footprint point's own chart address (its level section and its
   * radius there); the samples' host chart addresses are joined by a natural
   * cubic over three turns, read on the middle one. The central spline supplies
   * its first and second derivatives. Each sample also keeps its station along
   * the breast's course.
   *
   * @param host The host's complete source: a straight course with level
   *   sections (the trunk).
   * @param f The footprint.
   * @evidence contracts/development/implementation.md#principled-implementation The host's inside is read in its own chart (a level section about a straight course); each footprint point is dropped on the skin at its own chart address; the chart samples are joined by a natural cubic over three turns.
   * @evidence contracts/development/implementation.md#clear-and-simple-structure Sample, join, read.
   * @evidence contracts/development/implementation.md#prohibited-implementation-shortcuts A host that is not straight and level and a footprint point past its stations are refused with their numbers; no stored loop enters.
   * @evidence contracts/development/implementation.md#efficient-algorithms 240 chart addresses and one source point each.
   * @evidence contracts/development/implementation.md#reuse-equivalent-work One source reader and two splines serve every read.
   * @evidence contracts/development/implementation.md#bound-retention-and-release-resources The readers retain the reader and the two splines.
   * @evidence contracts/development/common.md#meaningful-documentation States the premises, units and refusals.
   */
  export function loop(host: IAutoMovieViewPart, f: IFootprint): ILoop {
    const source: IAutoMovieLoftViewFullSource.IReader =
      AutoMovieLoftViewFullSource.create(host);
    const { foot, tangent } = straight(host, source);
    const chart = (p: V): [number, number, number] => {
      const q: V = sub(p, [...foot!.origin] as V);
      const [x, y]: [number, number] = [
        dot(q, [...foot!.u] as V),
        dot(q, [...foot!.v] as V),
      ];
      return [
        source.domain[0] + dot(q, tangent),
        Math.atan2(y, x),
        Math.hypot(x, y),
      ];
    };
    // Project along the original host radius at each footprint address.
    const samples = Array.from({ length: CLOCKS }, (_, k: number) => {
      const c: number = (2 * Math.PI * k) / CLOCKS;
      const [s, phi] = chart(at(f, c));
      if (!(s > source.domain[0] && s < source.domain[1]))
        throw new Error(
          "mammary: the footprint's point at clock " +
            c +
            " stands at host station " +
            s +
            ", outside " +
            source.domain.join(" to "),
        );
      return {
        station: dot(sub(source.point(s, phi) as V, f.origin), f.along),
        s,
        phi,
      };
    }); // Three turns, so the middle one's natural end conditions have died away and the curve closes C2.
    const xs: number[] = [],
      ss: number[] = [],
      ps: number[] = [];
    for (let turn: number = -1; turn <= 1; ++turn)
      samples.forEach((q, k: number): void => {
        xs.push((2 * Math.PI * (k + turn * CLOCKS)) / CLOCKS);
        ss.push(q.s);
        ps.push(q.phi);
      });
    const sSpline: IAutoMovieNaturalCubicSpline = AutoMovieNaturalSpline.create(
      xs,
      ss,
    );
    const pSpline: IAutoMovieNaturalCubicSpline = AutoMovieNaturalSpline.create(
      xs,
      ps,
    );
    const hostAt: IAutoMovieSolidSharedCurve.Loop = (clock: number) => {
      const c: number = ((clock % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
      const [s, s1, s2] = AutoMovieNaturalSpline.read(sSpline, c);
      const [p, p1, p2] = AutoMovieNaturalSpline.read(pSpline, c);
      return { point: [s, p], first: [s1, p1], second: [s2, p2] };
    };
    const jetAt = (clock: number): { point: V; first: V; second: V } => {
      const q = hostAt(clock),
        h = source.jet(q.point[0], q.point[1]);
      const [a, b] = q.first,
        [aa, bb] = q.second;
      return {
        point: [...h.p] as V,
        first: add(scale([...h.u] as V, a), scale([...h.v] as V, b)),
        second: add(
          add(scale([...h.uu] as V, a * a), scale([...h.uv] as V, 2 * a * b)),
          add(
            scale([...h.vv] as V, b * b),
            add(scale([...h.u] as V, aa), scale([...h.v] as V, bb)),
          ),
        ),
      };
    };
    return {
      at: jetAt,
      hostAt,
      stations: samples.map((q): number => q.station),
    };
  }

  /**
   * The host's foot frame and course tangent, refused unless its course is
   * straight with level sections.
   */
  function straight(
    host: IAutoMovieViewPart,
    source: IAutoMovieLoftViewFullSource.IReader,
  ): { foot: IAutoMovieLoftSectionFrame; tangent: V } {
    const [foot, head]: IAutoMovieLoftSectionFrame[] = [
      host.axis.at(source.domain[0]),
      host.axis.at(source.domain[1]),
    ];
    const run: V = sub([...head!.origin] as V, [...foot!.origin] as V);
    const length: number = Math.hypot(...run);
    const tangent: V = scale(run, 1 / length);
    if (
      Math.abs(length - (source.domain[1] - source.domain[0])) > 1e-6 ||
      Math.abs(dot(tangent, [...foot!.u] as V)) > 1e-9
    )
      throw new Error(
        "mammary: the host's course is not straight with level sections",
      );
    return { foot: foot!, tangent };
  }

  function add(a: V, b: V): V {
    return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
  }
  function sub(a: V, b: V): V {
    return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
  }
  function scale(a: V, k: number): V {
    return [a[0] * k, a[1] * k, a[2] * k];
  }
  function dot(a: V, b: V): number {
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  }
  function cross(a: V, b: V): V {
    return [
      a[1] * b[2] - a[2] * b[1],
      a[2] * b[0] - a[0] * b[2],
      a[0] * b[1] - a[1] * b[0],
    ];
  }
}
